import jsPDF from 'jspdf';
import PAPER_BG from '../utils/paperBg';
import { SPECIAL_ELITE_B64 } from '../utils/specialEliteFont';

const DANCING_B64 = '';
const STAMP_B64 = 'data:image/png;base64,';

const INK       = [30,  15,  5];
const INK_LIGHT = [80,  45, 10];
const GOLD      = [130, 90,  20];
const RED       = [160,  0,   0];
const BLUE_INK  = [26,  58, 110];
const W = 210;
const H = 297;

function setFill(doc, rgb) { doc.setTextColor(rgb[0], rgb[1], rgb[2]); }
function setDraw(doc, rgb) { doc.setDrawColor(rgb[0], rgb[1], rgb[2]); }

function addFonts(doc) {
  doc.addFileToVFS('SpecialElite.ttf', SPECIAL_ELITE_B64);
  doc.addFont('SpecialElite.ttf', 'SpecialElite', 'normal');
  doc.addFileToVFS('DancingScript.ttf', DANCING_B64);
  doc.addFont('DancingScript.ttf', 'DancingScript', 'normal');
}

function drawPageBg(doc) {
  doc.addImage(PAPER_BG, 'JPEG', 0, 0, W, H);
}

function sep(doc, y) {
  setDraw(doc, GOLD); doc.setLineWidth(0.3);
  doc.line(18, y, W - 18, y);
  setFill(doc, GOLD); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(7);
  doc.text('*', W / 2, y + 3, { align: 'center' });
  return y + 7;
}

function sec(doc, y, txt) {
  setFill(doc, GOLD); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(11);
  doc.text(txt, 18, y);
  return y + 8;
}

function row(doc, label, value, y) {
  setFill(doc, INK_LIGHT); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(9.5);
  doc.text(label, 18, y);
  setFill(doc, INK); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(9.5);
  doc.text(String(value || '-'), 65, y);
  return y + 5.5;
}

function footer(doc, page, total) {
  setFill(doc, INK_LIGHT); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(7);
  doc.text('Police de Lemoyne  -  Comte de Lemoyne  -  1905  -  DOCUMENT CONFIDENTIEL          Page ' + page + ' / ' + total,
    W / 2, H - 10, { align: 'center' });
}

function checkBreak(doc, y, pageRef, fs) {
  if (y > H - 55) {
    footer(doc, pageRef.current, '?');
    doc.addPage();
    drawPageBg(doc);
    addFonts(doc);
    doc.setFont('SpecialElite', 'normal');
    if (fs) doc.setFontSize(fs);
    pageRef.current++;
    return 55;
  }
  return y;
}

export function exportGroupePDF(groupe, enqs, plaintes, citoyensInfo, showNotif) {
  try {
    var doc = new jsPDF({ unit: 'mm', format: 'a4' });
    addFonts(doc);
    var pageRef = { current: 1 };

    drawPageBg(doc);
    var y = 52;

    // EN-TETE
    setFill(doc, RED); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(13);
    doc.text('DOSSIER DE GROUPE - ' + (groupe.nom || '').toUpperCase(), W / 2, y, { align: 'center' }); y += 6;
    setFill(doc, INK_LIGHT); doc.setFontSize(8.5);
    doc.text('CONFIDENTIEL - USAGE INTERNE POLICE DE LEMOYNE', W / 2, y, { align: 'center' }); y += 8;

    y = sep(doc, y);

    // INFOS GROUPE
    y = sec(doc, y, '- INFORMATIONS GENERALES -');
    y = row(doc, 'Nom du groupe :', groupe.nom, y);
    y = row(doc, 'Territoire connu :', groupe.territoire || '-', y);
    y = row(doc, 'Nb membres :', (groupe.membres || []).length + ' membre(s)', y);
    y += 2; y = sep(doc, y);

    // NOTES
    if (groupe.notes) {
      y = checkBreak(doc, y, pageRef, 9.5);
      y = sec(doc, y, '- NOTES ET OBSERVATIONS -');
      var noteLines = doc.splitTextToSize(groupe.notes, W - 36);
      setFill(doc, INK); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(9.5);
      for (var ni = 0; ni < noteLines.length; ni++) {
        y = checkBreak(doc, y, pageRef, 9.5);
        doc.text(noteLines[ni], 18, y); y += 5.2;
      }
      y += 2; y = sep(doc, y);
    }

    // SUSPICIONS
    if (groupe.suspicions) {
      y = checkBreak(doc, y, pageRef, 9.5);
      y = sec(doc, y, '- SUSPICIONS -');
      var susLines = doc.splitTextToSize(groupe.suspicions, W - 36);
      setFill(doc, RED); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(9.5);
      for (var si = 0; si < susLines.length; si++) {
        y = checkBreak(doc, y, pageRef, 9.5);
        doc.text(susLines[si], 18, y); y += 5.2;
      }
      y += 2; y = sep(doc, y);
    }

    // PSEUDONYMES
    if (groupe.pseudonymes) {
      y = checkBreak(doc, y, pageRef, 9.5);
      y = sec(doc, y, '- PSEUDONYMES / ALIASES CONNUS -');
      var psLines = doc.splitTextToSize(groupe.pseudonymes, W - 36);
      setFill(doc, INK_LIGHT); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(9.5);
      for (var pi = 0; pi < psLines.length; pi++) {
        y = checkBreak(doc, y, pageRef, 9.5);
        doc.text(psLines[pi], 18, y); y += 5.2;
      }
      y += 2; y = sep(doc, y);
    }

    // MEMBRES
    if ((groupe.membres || []).length > 0) {
      y = checkBreak(doc, y, pageRef, 9.5);
      y = sec(doc, y, '- MEMBRES IDENTIFIES (' + groupe.membres.length + ') -');
      groupe.membres.forEach(function(m, i) {
        y = checkBreak(doc, y, pageRef, 9.5);
        var info = (citoyensInfo && citoyensInfo[m.citoyenId]) || {};
        var statut = info.statut || 'actif';
        var mw = info.mostWanted || false;
        var nom = ((m.prenom || '') + ' ' + (m.nom || '')).trim() || 'Inconnu';
        setFill(doc, mw ? RED : INK); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(10);
        var nomTxt = nom;
        if (mw) nomTxt += '  [MOST WANTED]';
        if (statut === 'decede') nomTxt += '  [DECEDE]';
        if (statut === 'disparu') nomTxt += '  [DISPARU]';
        doc.text(nomTxt, 18, y); y += 5;
        if (m.role) {
          setFill(doc, GOLD); doc.setFontSize(9);
          doc.text('Role : ' + m.role, 22, y); y += 4.5;
        }
        if (m.pseudo) {
          setFill(doc, INK_LIGHT); doc.setFontSize(9);
          doc.text('Alias : ' + m.pseudo, 22, y); y += 4.5;
        }
        y += 1.5;
      });
      y += 2; y = sep(doc, y);
    }

    // ENQUETES
    if (enqs && enqs.length > 0) {
      y = checkBreak(doc, y, pageRef, 9.5);
      y = sec(doc, y, "- DOSSIERS D'ENQUETE (" + enqs.length + ') -');
      enqs.forEach(function(enq) {
        y = checkBreak(doc, y, pageRef, 9.5);
        setFill(doc, GOLD); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(9.5);
        doc.text(enq.titre || 'Enquete sans titre', 18, y); y += 5;
        setFill(doc, INK_LIGHT); doc.setFontSize(8.5);
        if (enq.date) { y = checkBreak(doc, y, pageRef, 8.5); doc.text(enq.date + (enq.heure ? ' a ' + enq.heure : ''), 22, y); y += 4.5; }
        if (enq.localisation) { y = checkBreak(doc, y, pageRef, 8.5); doc.text('Localisation : ' + enq.localisation, 22, y); y += 4.5; }
        if (enq.contact) { y = checkBreak(doc, y, pageRef, 8.5); doc.text('Contact(s) : ' + enq.contact, 22, y); y += 4.5; }
        if (enq.membres) { y = checkBreak(doc, y, pageRef, 8.5); doc.text('Membres impliques : ' + enq.membres, 22, y); y += 4.5; }
        if (enq.elementsEnquete) {
          var eLines = doc.splitTextToSize('Elements : ' + enq.elementsEnquete, W - 36);
          setFill(doc, BLUE_INK);
          for (var ei = 0; ei < eLines.length; ei++) {
            y = checkBreak(doc, y, pageRef, 8.5);
            doc.text(eLines[ei], 22, y); y += 4.5;
          }
        }
        y += 3;
        setDraw(doc, GOLD); doc.setLineWidth(0.15);
        doc.line(22, y - 1, W - 22, y - 1);
        y += 2;
      });
      y = sep(doc, y);
    }

    // PLAINTES LIEES
    if (plaintes && plaintes.length > 0) {
      y = checkBreak(doc, y, pageRef, 9.5);
      y = sec(doc, y, '- PLAINTES LIEES (' + plaintes.length + ') -');
      plaintes.forEach(function(p) {
        y = checkBreak(doc, y, pageRef, 9.5);
        setFill(doc, INK); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(9.5);
        var pTxt = (p.date || '-') + '  -  ' + (p.statut || '').toUpperCase();
        doc.text(pTxt, 18, y); y += 5;
        if (p.faits) {
          var pLines = doc.splitTextToSize(p.faits.substring(0, 200) + (p.faits.length > 200 ? '...' : ''), W - 36);
          setFill(doc, INK_LIGHT); doc.setFontSize(8.5);
          for (var pli = 0; pli < Math.min(pLines.length, 3); pli++) {
            y = checkBreak(doc, y, pageRef, 8.5);
            doc.text(pLines[pli], 22, y); y += 4.5;
          }
        }
        y += 2;
      });
      y = sep(doc, y);
    }

    // PAGE SIGNATURE
    var totalPages = pageRef.current + 1;
    footer(doc, pageRef.current, totalPages);
    doc.addPage(); drawPageBg(doc); addFonts(doc);
    y = 55;
    setFill(doc, INK_LIGHT); doc.setFont('SpecialElite', 'normal'); doc.setFontSize(9.5);
    doc.text("Signature de l'Agent Redacteur", 18, y);
    doc.text('Cachet de la Police de Lemoyne', W - 18, y, { align: 'right' });
    y += 12;
    setFill(doc, INK_LIGHT); doc.setFont('DancingScript', 'normal'); doc.setFontSize(16);
    doc.text(groupe.agentRedacteur || '', 18, y);
    var stampSize = 38;
    doc.addImage(STAMP_B64, 'PNG', W - 18 - stampSize, y - stampSize * 0.75, stampSize, stampSize * 0.95);
    footer(doc, totalPages, totalPages);

    var filename = 'Groupe_' + (groupe.nom || 'inconnu').replace(/ /g, '_') + '.pdf';
    doc.save(filename);
    if (showNotif) showNotif('PDF exporte !');
  } catch (e) {
    console.error(e);
    if (showNotif) showNotif('Erreur PDF : ' + e.message, true);
  }
}
